-- Modify "problems" table
ALTER TABLE "public"."problems" ADD COLUMN "submission_count" bigint NOT NULL DEFAULT 0, ADD COLUMN "accepted_count" bigint NOT NULL DEFAULT 0;
-- Create "user_solved_problems" table
CREATE TABLE "public"."user_solved_problems" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "solved_at" timestamptz NOT NULL,
  "problem_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_solved_problems_problems_solvers" FOREIGN KEY ("problem_id") REFERENCES "public"."problems" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "user_solved_problems_users_solved_problems" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "usersolvedproblem_user_id" to table: "user_solved_problems"
CREATE INDEX "usersolvedproblem_user_id" ON "public"."user_solved_problems" ("user_id");
-- Create index "usersolvedproblem_user_id_problem_id" to table: "user_solved_problems"
CREATE UNIQUE INDEX "usersolvedproblem_user_id_problem_id" ON "public"."user_solved_problems" ("user_id", "problem_id");
